This Terraform configuration deploys a basic Amazon Lightsail instance in the AWS `us-east-1` region. It provisions a small Linux-based Lightsail virtual server using an Ubuntu blueprint and the smallest available bundle size. Default variables are included so the configuration can be deployed without modification.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the Lightsail instance will be created."
  type        = string
  default     = "us-east-1"
}

variable "availability_zone" {
  description = "Availability zone for the Lightsail instance."
  type        = string
  default     = "us-east-1a"
}

variable "instance_name" {
  description = "Name of the Lightsail instance."
  type        = string
  default     = "basic-lightsail-instance"
}

variable "blueprint_id" {
  description = "Lightsail blueprint ID for the operating system or application."
  type        = string
  default     = "ubuntu_22_04"
}

